    /// <summary>
    /// Pins a message in a chat. A message can be pinned only if messageProperties.can_be_pinned
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> PinChatMessageAsync(long chatId = default, long messageId = default, bool disableNotification = default, bool onlyForSelf = default)
    {

           using var activity =  StartCallActivity("PinChatMessageAsync", typeof(PinChatMessage).FullName ?? "PinChatMessageAsync");

           try
           {
             return client.PinChatMessageAsync(chatId, messageId, disableNotification, onlyForSelf);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
